// src/components/App.js
import '../index.css';
import { useState } from 'react';
import TonalitySelector from './TonalitySelector';
import SettingsPanel from './SettingsPanel';
import OutputDisplay from './OutputDisplay';
import useChordGenerator from '../hooks/useChordGenerator';
import { keyPairs, allChords } from '../data/vocabulary'; // Импортируем нужные данные

function App() {
  const [selectedIndexes, setSelectedIndexes] = useState([]); // Хук для чекбоксов

  const handleCheckboxChange = (e) => {
    const value = parseInt(e.target.value);
    if (isNaN(value)) return;
    e.target.checked
      ? setSelectedIndexes([...selectedIndexes, value])
      : setSelectedIndexes(selectedIndexes.filter(i => i !== value));
  };

  const {
    state,
    sequence,
    sequenceLength,
    forbidVtoIV,
    handleInput, // Главная функция из хука
  } = useChordGenerator();

  const handleFormSubmit = (e) => {
    e.preventDefault();
    if (selectedIndexes.length > 0) {
        handleInput(selectedIndexes.join(''));
    }
  };

  return (
    <div className="min-h-screen bg-gray-900 text-white p-8">
      <h1 className="text-3xl font-bold mb-4 text-center">Генератор аккордов</h1>

      {/* Блок кнопок и таблицы, который виден, когда НЕТ результата */}
      {sequence.length === 0 && (
        <div className="space-y-8 text-center">
          <p className="text-lg mt-10">
            Нажмите кнопку для генерации или выберите тональность из таблицы.
          </p>
          
          <div className="flex flex-col sm:flex-row justify-center gap-3 mb-8">
            <button
              onClick={() => handleInput('0')}
              className="w-full sm:w-auto bg-gray-700 hover:bg-gray-600 text-white font-medium py-2 px-4 rounded"
            >
              🎲 Случайная тональность
            </button>
            <button
              onClick={() => handleInput('00')}
              className="w-full sm:w-auto bg-green-600 hover:bg-green-700 text-white font-medium py-2 px-4 rounded"
            >
              ⚡️ Быстрая генерация
            </button>
          </div>

          {/* Таблица всегда видна на стартовом экране */}
          <div className="max-w-md mx-auto bg-gray-800 rounded-md shadow-lg overflow-hidden">
            <TonalitySelector keyPairs={keyPairs} onSelect={handleInput} />
          </div>
        </div>
      )}

      {/* Блок, который виден, когда ЕСТЬ результат */}
      {sequence.length > 0 && (
        <>
          <div className="grid md:grid-cols-2 gap-8">
            {/* Левая колонка - Настройки */}
            <div>
              {/* Таблица здесь больше не нужна, чтобы не дублировалась */}
              <div className="mt-6">
                <h2 className="text-xl font-semibold mb-2">Настройки</h2>
                <SettingsPanel onChange={handleInput} />
              </div>
            </div>
            
            {/* Правая колонка - Результат */}
            <div>
              <div className="mb-6">
                <h2 className="text-xl font-semibold mb-2">Ваша последовательность</h2>
                <OutputDisplay sequence={sequence} />
              </div>
              
              <div className="space-y-2">
                <button 
                  onClick={() => handleInput('generate')} 
                  disabled={state !== 'askRepeat'}
                  className={`w-full py-2 px-4 rounded-lg ${
                    state === 'askRepeat' ? 'bg-blue-500 hover:bg-blue-700' : 'bg-gray-600 cursor-not-allowed'
                  } text-white font-medium`}
                >
                  Сгенерировать снова ({sequenceLength})
                </button>
                
                <button
                  onClick={() => handleInput('reset')}
                  className="w-full bg-gray-700 hover:bg-gray-600 text-white font-medium py-2 px-4 rounded-lg"
                >
                  Начать заново / Выбрать тональность
                </button>
              </div>
            </div>
          </div>
        </>
      )}
    </div>
  );
}

export default App;
